__NUXT_JSONP__("/jp/how-to-apply/short", (function(a){return {data:[{details:{slug:"jp",pageTitle:"海外からの短期留学申込 | Mentor Language Institute",pageDescription:a,title:"海外からの短期留学申込",image:"\u002Fimages\u002Fshort\u002Fpassport-jp.jpg",category:[{title:a,content:["学生ビザを取得しない短期留学生が対象です。","―現在は日本（アメリカ国外）に滞在している\u003Cbr \u002F\u003E―アメリカに滞在する日数が90日未満"]},{title:"手続きの手順",image:"\u002Fimages\u002Fshort\u002Fmli-design-apply-short-jp.jpg",ordered_content:["お申し込み","必要書類の提出（滞在申込書）","ファイナルコンファーメーション及び滞在詳細の受領","渡米"],content:["短期留学生はビザの手続きがありません。よって手続き自体に日数は要しませんが、教室や滞在先確保を確実にするためにもお込みはお早めにお願いします。","とりわけ夏休みや春休みなどの繁忙期は混雑が予想されます。\u003Cb\u003E短期留学であっても2ヵ月前にはお申込みを終えて頂くようお勧めいたします。\u003C\u002Fb\u003E"],types:[{title:"キャンセル規定",content:["お申込み時に発生する入学金$150はお手続き開始後はいかなる理由があっても返金出来ませんので予めご了承下さい。ただし、滞在先が満室のため受け入れが出来ない、など当校が事由の場合は、その限りではありません。"]}]},{title:"お申し込み後の手続きの進め方について",image:"\u002Fimages\u002Fshort\u002Fmli-short-jp.jpg",content:["お申し込み後はiMLIと言う当校独自の申し込みシステムにより手続きを進めて参ります。\u003Cbr \u002F\u003E手続き方法はiMLIに記載され、ひとつひとつ順を追って進めていく事が可能です。"],types:[{title:"お申込みはこちら",content:["以下の申込みフォームより必要事項をご記入下さい。"]}]}],btn_label:"オンライン申込フォームへ",admission:{link:"\u002Fjp\u002Fadmission",content:["※お申込み時はクレジットカードをご用意ください。"]},dir:"\u002Fshort",path:"\u002Fshort\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:31.067Z",updatedAt:"2025-05-26T12:06:27.916Z"}}],fetch:{},mutations:void 0}}("滞在期間90日未満の留学生")));